SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', -2, 5), instr('a%b', ' pad '), replace('a%b', 'e', 'XY'), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE '%', 'a%b' GLOB '*', char(71, 573), 'a%b' || ' pad ', 'a%b' < ' pad ', 'a%b' = ' pad ' COLLATE NOCASE;
SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', -2, 0), instr('0x1F', '0x1F'), replace('0x1F', 'é', 'XY'), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE 'A%', '0x1F' GLOB '?', char(70, 968), '0x1F' || '0x1F', '0x1F' < '0x1F', '0x1F' = '0x1F' COLLATE NOCASE;
SELECT length(' pad '), upper(' pad '), lower(' pad '), substr(' pad ', -3, 3), instr(' pad ', 'nu'), replace(' pad ', 'é', ''), trim(' pad '), ltrim(' pad ', 'ab'), hex(' pad '), quote(' pad '), unicode(' pad '), ' pad ' LIKE '_', ' pad ' GLOB '*[a-m]*', char(75, 716), ' pad ' || 'nu', ' pad ' < 'nu', ' pad ' = 'nu' COLLATE NOCASE;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', 0, 5), instr('-7', 'phi'), replace('-7', 'e', '_'), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE '%a_', '-7' GLOB '*[a-m]*', char(74, 653), '-7' || 'phi', '-7' < 'phi', '-7' = 'phi' COLLATE NOCASE;
SELECT length('café'), upper('café'), lower('café'), substr('café', 1, 0), instr('café', 'Ελλάδα'), replace('café', 'a', ''), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE '%', 'café' GLOB '*[a-m]*', char(86, 607), 'café' || 'Ελλάδα', 'café' < 'Ελλάδα', 'café' = 'Ελλάδα' COLLATE NOCASE;
SELECT length('alpha'), upper('alpha'), lower('alpha'), substr('alpha', -1, 2), instr('alpha', 'omicron'), replace('alpha', 'e', ''), trim('alpha'), ltrim('alpha', 'ab'), hex('alpha'), quote('alpha'), unicode('alpha'), 'alpha' LIKE '%a_', 'alpha' GLOB '*', char(79, 362), 'alpha' || 'omicron', 'alpha' < 'omicron', 'alpha' = 'omicron' COLLATE NOCASE;
SELECT length('42'), upper('42'), lower('42'), substr('42', 2, 1), instr('42', 'phi'), replace('42', '', 'XY'), trim('42'), ltrim('42', 'ab'), hex('42'), quote('42'), unicode('42'), '42' LIKE '%é%', '42' GLOB '*[a-m]*', char(81, 277), '42' || 'phi', '42' < 'phi', '42' = 'phi' COLLATE NOCASE;
SELECT count(*), count(c2), sum(c2), total(c2), avg(c2), min(c2), max(c2), count(DISTINCT c2) FROM t1 WHERE (-(id) OR -(c1));
SELECT c2, count(*), group_concat(id, ';') FROM (SELECT * FROM t1 ORDER BY id) GROUP BY c2 ORDER BY c2;
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY id DESC, id;
SELECT id FROM t0 WHERE id IN (SELECT id FROM t1) ORDER BY id;
SELECT id FROM t0 x WHERE NOT EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 2) ORDER BY id;
SELECT c0 FROM t0 INTERSECT SELECT c0 FROM t1 ORDER BY 1 LIMIT 18 OFFSET 1;
SELECT id, nullif(x'1bf8', NOT CASE WHEN id THEN NULL ELSE c0 END), iif(x'36a0b64788', c0, NULL) FROM t0 ORDER BY id DESC, c0, c1, c2 DESC;
SELECT iif(NULL, typeof(x''), x''), typeof(582);
